function s(v){return String(v==null?'':v).trim();}
function nz(x){return s(x).toLowerCase().replace(/[^a-z0-9]/g,'');}
function colL(i){let n=i+1,t='';while(n>0){const m=(n-1)%26;t=String.fromCharCode(65+m)+t;n=Math.floor((n-1)/26);}return t;}
const b=$('Webhook').first().json.body||{};if(b.secret!=='sv-crit-2026-09-17-q8Lz'){throw new Error('bad secret');}const dry=b.dry!==false;
const TERMS=['artha.vc','bvp.com','lightbox.vc','pravegavc.com','capital-a.vc','indicornangels.com','karekeba.com','alexanderalpert@gmail.com','sparkseedventures.in','mohit@indiaquotient.in','duovalle.cap@gmail.com','incredcapital.com','pentathlon.vc'];
const hit=e=>{const a=s(e).toLowerCase().split(/[,;\s]+/).filter(Boolean);return a.some(x=>TERMS.some(t=>t.indexOf('@')>=0?x===t:x.endsWith('@'+t)));};
const vr=$('GET pilot').first().json.valueRanges||[];const inv=(vr[0]||{}).values||[],crit=(vr[1]||{}).values||[],pipe=(vr[2]||{}).values||[];
if(inv.length<150||crit.length<200||pipe.length<5000){throw new Error('ABORT short read');}
const TODAY=new Date(Date.now()+330*60000).toISOString().slice(0,10);
const data=[];const put=(r,v)=>data.push({range:r,values:[[v]]});
const names={};const invRows=[];
for(let i=1;i<inv.length;i++){const r=inv[i]||[];if(hit(s(r[2])+','+s(r[3]))){names[nz(r[0])]=s(r[0]);invRows.push((i+1)+' '+s(r[0])+' <'+s(r[2])+'>');put('INVESTORS!J'+(i+1),'Yes');}}
const ch=crit[0].map(s);const CX={};ch.forEach((k,i)=>CX[k]=i);const critRows=[];
for(let i=1;i<crit.length;i++){const r=crit[i]||[];if(names[nz(r[CX.investor])]){critRows.push((i+1)+' '+s(r[CX.investor])+' was '+s(r[CX.status]));put('INVESTOR_CRITERIA!'+colL(CX.status)+(i+1),'DNC');put('INVESTOR_CRITERIA!'+colL(CX.rule_notes)+(i+1),(s(r[CX.rule_notes])?s(r[CX.rule_notes])+' | ':'')+'REMOVED by user '+TODAY+': never replied to any email since the first deal');}}
const ph=pipe[0].map(s);const X={};ph.forEach((k,i)=>X[k]=i);let dropped=0,stopped=0;const byInv={};
for(let i=1;i<pipe.length;i++){const r=pipe[i]||[];const g=k=>s(r[X[k]]);if(!(names[nz(g('investor'))]||hit(g('email')))){continue;}
  const rn=i+1;const sent=/^yes$/i.test(g('deal_shared'));const paused=/^yes$/i.test(g('pause'));const notes=g('notes');
  if(!sent){if(paused){continue;}put('PIPELINE!'+colL(X.pause)+rn,'Yes');put('PIPELINE!'+colL(X.next_action)+rn,'DROPPED - investor removed (never replied)');put('PIPELINE!'+colL(X.notes)+rn,(notes?notes+' | ':'')+'Investor removed by user '+TODAY+' (never replied)');dropped++;byInv[g('investor')]=(byInv[g('investor')]||0)+1;}
  else if(!paused&&!g('investor_response')){put('PIPELINE!'+colL(X.pause)+rn,'Yes');put('PIPELINE!'+colL(X.notes)+rn,(notes?notes+' | ':'')+'Investor removed by user '+TODAY+' (never replied) - follow-ups stopped');stopped++;}
}
if(invRows.length<13||invRows.length>20){throw new Error('ABORT expected 13-20 INVESTORS rows, got '+invRows.length+': '+invRows.join(' ; '));}
return [{json:{dry:dry,investors_rows:invRows,criteria_rows:critRows,queued_dropped:dropped,followups_stopped:stopped,dropped_by_investor:byInv,cells:data.length,data:dry?[]:data}}];
